style.css:
@-moz-document domain("spotify.com") {
body {
        background-color: #ffccdd !important;
        color: #ff6699 !important;
    }

    .Root__top-container,
    .Root__nav-bar,
    .Root__main-view,
    .Root__main-container,
    .navBar-navBar,
    .main-view-container,
    .main-view-container__scroll-node-child,
    .progress-bar,
    .volume-bar,
    .button,
    .play-button,
    .control-button,
    .sidebar,
    .footer,
    .tracklist,
    .playlist-list,
    .playlist-item,
    .playlist-item__name,
    .playlist-item__info {
        background-color: #ff99bb !important;
        color: #ffffff !important;
    }

    .navBar-navBar a,
    .button,
    .play-button,
    .control-button,
    .track-name,
    .album-name,
    .artist-name,
    .playlist-item__name,
    .playlist-item__info {
        color: #ff3366 !important;
    }

    .button:hover,
    .play-button:hover,
    .control-button:hover,
    .playlist-item:hover {
        background-color: #ff6699 !important;
    }
}
